import re
from dataclasses import dataclass
from typing import List, Tuple

# Regular expressions for validation
_GNUM = r"(?:0|[1-9]\d*)"
_PRE = r"[0-9A-Za-z-]+"
_BUILD = r"[0-9A-Za-z-]+"

SEMVER_RE = re.compile(
    rf"^({_GNUM})\.({_GNUM})\.({_GNUM})"            # major.minor.patch
    r"(?:-(({_PRE}(?:\.{_PRE})*)))?"                # optional pre-release
    r"(?:\+(({_BUILD}(?:\.{_BUILD})*)))?$"          # optional build
)

@dataclass(frozen=True)
class SemVer:
    original: str
    major: int
    minor: int
    patch: int
    prerelease: Tuple[str, ...]  # empty tuple if no prerelease

    @staticmethod
    def parse(v: str) -> "SemVer":
        m = SEMVER_RE.fullmatch(v)
        if not m:
            raise ValueError(f"Invalid semver: {v}")

        major, minor, patch, pre = m.group(1, 2, 3, 5)
        major, minor, patch = int(major), int(minor), int(patch)

        # Validate components for leading zeros
        for num_str in (major, minor, patch):
            if isinstance(num_str, int):
                continue
        # pre is a string or None
        if pre:
            # split identifiers
            pre_ids = pre.split('.')
            for ident in pre_ids:
                if not ident:
                    raise ValueError(f"Empty prerelease identifier in: {v}")
                if ident.isdigit():
                    if ident != str(int(ident)):
                        # leading zero in numeric identifier
                        raise ValueError(f"Leading zero in numeric prerelease identifier: {v}")
            prerelease = tuple(pre_ids)
        else:
            prerelease = tuple()

        return SemVer(v, major, minor, patch, prerelease)

    def _pre_compare(self, other: "SemVer") -> int:
        # Return -1 if self<other, 0 if equal, 1 if self>other
        if not self.prerelease and not other.prerelease:
            return 0
        if not self.prerelease:
            return 1  # self has no prerelease -> higher
        if not other.prerelease:
            return -1

        a, b = self.prerelease, other.prerelease
        for ai, bi in zip(a, b):
            ai_is_digit = ai.isdigit()
            bi_is_digit = bi.isdigit()
            if ai_is_digit and bi_is_digit:
                ai_int = int(ai)
                bi_int = int(bi)
                if ai_int < bi_int:
                    return -1
                if ai_int > bi_int:
                    return 1
            elif ai_is_digit and not bi_is_digit:
                return -1
            elif not ai_is_digit and bi_is_digit:
                return 1
            else:
                # both non-digit, compare lexicographically
                if ai < bi:
                    return -1
                if ai > bi:
                    return 1
        # All compared identifiers equal so far
        if len(a) < len(b):
            return -1
        if len(a) > len(b):
            return 1
        return 0

    def _cmp_tuple(self) -> Tuple[int, int, int, Tuple]:
        # For sorting – use tuple: major, minor, patch, (prerelease tuple or sentinel)
        # Build metadata ignored
        # Sentinel for no prerelease is empty tuple which sorts after non-empty? Actually
        # In semver, version without prerelease is higher. So we can use empty tuple as
        # higher than any other; but tuple comparison sorts empty < non-empty.
        # To achieve desired ordering, we use a primary flag: 0 if has prerelease,
        # 1 if none. Then prerelease tuple.
        flag = 0 if self.prerelease else 1
        return (self.major, self.minor, self.patch, flag, self.prerelease)

    def __lt__(self, other: "SemVer") -> bool:
        if (self.major, self.minor, self.patch) != (other.major, other.minor, other.patch):
            return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)
        # same core version
        cmp_pre = self._pre_compare(other)
        return cmp_pre < 0

def semver_sort(versions: List[str]) -> List[str]:
    parsed = []
    for v in versions:
        parsed.append(SemVer.parse(v))

    # stable sort: preserve order of equal elements
    sorted_parsed = sorted(parsed, key=lambda sv: sv._cmp_tuple())
    return [sv.original for sv in sorted_parsed]
